<p class="eyebrow">Country Pack</p><h1><?= e($country['name']) ?></h1><p class="muted">Stable ISO identifiers and slug are protected. Changes are saved to this Country Pack only.</p><div class="admin-tabs"><a href="#general">General</a><a href="#theme">Theme</a><a href="#branding">Branding</a><a href="#content">Homepage</a><a href="#legal">Legal</a><a href="#license">Licence</a><a href="#faq">FAQ</a><a href="#images">Images</a></div><section id="general" class="card"><h2>General and currency</h2><form method="post" action="<?= e(route('admin.countries.update',['country'=>$country['id']])) ?>" class="form-stack"><?= app('csrf')->input() ?><div class="form-grid"><label class="field">Display name<input name="name" value="<?= e($country['name']) ?>" required></label><label class="field">Local name<input name="local_name" value="<?= e($country['local_name']) ?>" required></label><label class="field">Currency code<input name="currency_code" maxlength="3" value="<?= e($country['currency_code']) ?>" required></label><label class="field">Currency symbol<input name="currency_symbol" value="<?= e($country['currency_symbol']) ?>" required></label><label class="field">Symbol position<select name="currency_symbol_position"><option value="before"<?= $country['currency_symbol_position']==='before'?' selected':'' ?>>Before</option><option value="after"<?= $country['currency_symbol_position']==='after'?' selected':'' ?>>After</option></select></label><label class="field">Locale<input name="locale" value="<?= e($country['locale']) ?>" required></label><label class="field">Timezone<input name="timezone" value="<?= e($country['timezone']) ?>" required></label><label class="field">Default language<select name="default_language_id"><?php foreach($languages as $language): ?><option value="<?= e($language['id']??'') ?>"<?= (int)$country['default_language_id']===(int)($language['id']??0)?' selected':'' ?>><?= e($language['native_name']) ?></option><?php endforeach;?></select></label><label class="field">Sort order<input type="number" name="sort_order" value="<?= e($country['sort_order']) ?>"></label></div><button class="button">Save Country Pack</button></form><hr><form method="post" action="<?= e(route('admin.countries.enabled',['country'=>$country['id']])) ?>" class="inline-form" data-confirm="Change Country Pack availability? Existing assigned users are not reassigned."><?= app('csrf')->input() ?><label class="check"><input type="checkbox" name="enabled" value="1"<?= !empty($country['is_enabled'])?' checked':'' ?><?= !empty($country['is_global'])?' disabled':'' ?>> Enable this Country Pack</label><button class="button button-secondary">Update availability</button></form></section>
<section id="theme" class="card"><h2>Theme editor</h2><form method="post" action="<?= e(route('admin.countries.theme',['country'=>$country['id']])) ?>" class="form-stack theme-form"><?= app('csrf')->input() ?><div class="form-grid"><?php foreach(['primary','secondary','accent','dark','background','surface','text','muted','border','success','warning','error'] as $color): ?><label class="field"><?= e(ucfirst($color)) ?><input type="color" name="<?= e($color) ?>" value="<?= e($country['theme'][$color]??'#1258D5') ?>" data-theme-color="<?= e($color) ?>"></label><?php endforeach;?></div><div class="form-grid"><label class="field">Heading font<select name="heading_font"><?php foreach(['Inter','system','Arial','Georgia','Noto Sans','Noto Sans Arabic','Noto Sans JP','Noto Sans KR'] as $font):?><option<?= ($country['theme']['heading_font']??'')===$font?' selected':'' ?>><?= e($font) ?></option><?php endforeach;?></select></label><label class="field">Body font<select name="body_font"><?php foreach(['Inter','system','Arial','Georgia','Noto Sans'] as $font):?><option><?= e($font) ?></option><?php endforeach;?></select></label><label class="field">Radius<select name="radius"><?php foreach(['8px','12px','16px','18px','24px'] as $radius):?><option<?= ($country['theme']['radius']??'')===$radius?' selected':'' ?>><?= e($radius) ?></option><?php endforeach;?></select></label></div><div class="theme-preview"><strong>Preview heading</strong><button type="button">Button</button><span>Card and badge preview</span></div><button class="button">Save theme</button></form></section>
<section id="branding" class="card"><h2>Branding and contact overrides</h2><form method="post" action="<?= e(route('admin.countries.branding',['country'=>$country['id']])) ?>" class="form-stack"><?= app('csrf')->input() ?><div class="form-grid"><?php foreach(['brand_name'=>'Brand name','short_name'=>'Short name','support_email'=>'Support email','support_phone'=>'Phone','support_whatsapp'=>'WhatsApp','support_hours'=>'Support hours','meta_title'=>'Meta title','meta_description'=>'Meta description'] as $key=>$label):?><label class="field"><?= e($label) ?><input name="<?= e($key) ?>" value="<?= e($branding[$key]??'') ?>"></label><?php endforeach;?></label></div><label class="field">Address<textarea name="business_address"><?= e($branding['business_address']??'') ?></textarea></label><label class="field">Footer/contact text<textarea name="footer_text"><?= e($branding['footer_text']??'') ?></textarea></label><div class="form-grid"><?php foreach(['facebook','instagram','linkedin','x','youtube','telegram'] as $key):?><label class="field"><?= e(ucfirst($key)) ?> URL<input name="social_<?= e($key) ?>" value="<?= e($branding['social_links'][$key]??'') ?>"></label><?php endforeach;?></div><button class="button">Save branding</button></form></section>
<section id="images" class="card"><h2>Images</h2><form method="post" enctype="multipart/form-data" action="<?= e(route('admin.countries.asset',['country'=>$country['id']])) ?>" class="form-stack"><?= app('csrf')->input() ?><label class="field">Slot<select name="asset_type"><?php foreach(['logo','dark_logo','favicon','hero','secondary_banner','about','investment','trust','contact'] as $slot):?><option><?= e($slot) ?></option><?php endforeach;?></select></label><label class="field">Image<input type="file" name="asset" accept="image/png,image/jpeg,image/webp" required></label><label class="field">Alt text<input name="alt_text"></label><button class="button">Upload image</button></form></section>
<section id="content" class="card"><h2>Homepage content</h2><form method="post" action="<?= e(route('admin.countries.content',['country'=>$country['id']])) ?>" class="form-stack"><?= app('csrf')->input() ?><input type="hidden" name="page_key" value="home"><label class="field">Language<select name="language_id"><?php foreach($languages as $language):?><option value="<?= e($language['id']??'') ?>"><?= e($language['native_name']) ?></option><?php endforeach;?></select></label><?php foreach(['hero_headline','hero_subheading','primary_cta','secondary_cta','intro_heading','intro_description','investment_heading','investment_body','trust_heading','trust_body','faq_intro','contact_intro','footer_text'] as $key):?><label class="field"><?= e(ucwords(str_replace('_',' ',$key))) ?><textarea name="<?= e($key) ?>" rows="2"></textarea></label><?php endforeach;?><button class="button">Save content version</button></form></section>
<section id="legal" class="card"><h2>Legal pages and history</h2><form method="post" action="<?= e(route('admin.countries.legal',['country'=>$country['id']])) ?>" class="form-stack"><?= app('csrf')->input() ?><div class="form-grid"><label class="field">Document<select name="document_type"><option value="terms">Terms</option><option value="privacy">Privacy</option><option value="risk-disclosure">Risk disclosure</option></select></label><label class="field">Language<select name="language_id"><?php foreach($languages as $language):?><option value="<?= e($language['id']??'') ?>"><?= e($language['native_name']) ?></option><?php endforeach;?></select></label><label class="field">Version<input name="version" placeholder="2026-01" required></label><label class="field">Effective date<input type="date" name="effective_at"></label></div><label class="field">Title<input name="title" required></label><label class="field">Sanitized HTML<textarea name="body" rows="8" required></textarea></label><label class="check"><input type="checkbox" name="published" value="1"> Publish immediately</label><button class="button">Create legal version</button></form><div class="table-wrap"><table><thead><tr><th>Document</th><th>Language</th><th>Version</th><th>Published</th></tr></thead><tbody><?php foreach($legal as $doc):?><tr><td><?= e($doc['document_type']) ?></td><td><?= e($doc['language_code']) ?></td><td><?= e($doc['version']) ?></td><td><?= !empty($doc['is_published'])?'Yes':'Draft' ?></td></tr><?php endforeach;?></tbody></table></div></section>
<section id="license" class="card"><h2>Licence</h2><p><?= $license?'Current status: '.e($license['calculated_status']):'No licence record.' ?></p><form method="post" enctype="multipart/form-data" action="<?= e(route('admin.countries.license',['country'=>$country['id']])) ?>" class="form-stack"><?= app('csrf')->input() ?><div class="form-grid"><?php foreach(['regulator_name'=>'Regulator','license_name'=>'Licence name','license_number'=>'Licence number'] as $key=>$label):?><label class="field"><?= e($label) ?><input name="<?= e($key) ?>"></label><?php endforeach;?><label class="field">Issue date<input type="date" name="issue_date"></label><label class="field">Expiry date<input type="date" name="expiry_date"></label><label class="field">Manual status<select name="manual_status"><option value="">Automatic</option><option>NOT_REQUIRED</option><option>SUSPENDED</option></select></label></div><label class="field">Actual PDF or image<input type="file" name="document" accept="application/pdf,image/png,image/jpeg,image/webp"></label><label class="field">Notes<textarea name="notes"></textarea></label><button class="button">Save licence record</button></form><form method="post" action="<?= e(route('admin.countries.license-settings',['country'=>$country['id']])) ?>" class="inline-form"><?= app('csrf')->input() ?><label class="check"><input type="checkbox" name="require_valid_license_for_investing" value="1"<?= !empty($licenseSettings['require_valid_license_for_investing'])?' checked':'' ?>> Require valid licence for future investing</label><label class="field">Warning days<input type="number" name="expiry_warning_days" value="<?= e($licenseSettings['expiry_warning_days']) ?>"></label><button class="button button-secondary">Save requirement</button></form></section>
<section id="faq" class="card"><h2>FAQ</h2><form method="post" action="<?= e(route('admin.countries.faq',['country'=>$country['id']])) ?>" class="form-stack"><?= app('csrf')->input() ?><div class="form-grid"><label class="field">Language<select name="language_id"><?php foreach($languages as $language):?><option value="<?= e($language['id']??'') ?>"><?= e($language['native_name']) ?></option><?php endforeach;?></select></label><label class="field">Category<input name="category"></label><label class="field">Order<input type="number" name="sort_order" value="0"></label></div><label class="field">Question<input name="question" required></label><label class="field">Answer<textarea name="answer" required></textarea></label><label class="check"><input type="checkbox" name="is_active" value="1" checked> Active</label><button class="button">Add FAQ</button></form></section>
